output_text:
[
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "Shopping carts are forbidden in single-file shelf aisles where the shopper is flanked by shelves on both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_enter_single_file_with_cart",
    "text": "A shopper must not move into a single-file shelf aisle while still pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "no_push_cart_north_from_top_aisle_mouth",
    "text": "At the mouth of a narrow top shelf aisle, the shopper may not push the cart north into the aisle.",
    "abstraction": {
      "state_properties": {
        "topAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "topAisleMouth",
          "hasCart",
          "N"
        ]
      }
    }
  },
  {
    "id": "cartless_only_for_narrow_aisle_excursion",
    "text": "Once a cart has been taken, walking without it is allowed only in a narrow shelf aisle or at the corresponding aisle mouth.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "topAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartlessExcursionZone": {
          "or": [
            "singleFileShelfAisle",
            "topAisleMouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "cartlessExcursionZone"
          }
        ]
      }
    }
  },
  {
    "id": "return_to_cart_after_cartless_shelf_pick",
    "text": "After interacting with a shelf while away from the cart, the shopper is obliged to return to and take the cart again before leaving.",
    "abstraction": {
      "state_properties": {
        "topAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "cartlessShelfInteract": {
          "pre": {
            "and": [
              "INTERACT",
              "adjShelf",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": null
        },
        "reacquireCartAtMouth": {
          "pre": {
            "and": [
              "INTERACT",
              "topAisleMouth",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartlessShelfInteract",
      "discharge": "reacquireCartAtMouth"
    }
  },
  {
    "id": "cart_required_for_open_shelf_service",
    "text": "Interacting with shelves from open shopping corridors requires having the cart, while single-file shelf aisles are exempt.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "openShelfFace": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "openShelfFace",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_horizontal_cart_travel_in_two_wide_side_bays",
    "text": "In a two-wide side bay beside shelves, carts may be moved only in or out vertically, not driven horizontally along the constricted bay.",
    "abstraction": {
      "state_properties": {
        "twoWideSideBay": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                2
              ]
            },
            {
              "gt": [
                "freeWidthV",
                2
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "twoWideSideBay",
          {
            "or": [
              "E",
              "W"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "avoid_vertical_cart_departure_from_short_shelf_bay",
    "text": "After servicing a shelf in a very short vertical bay, the shopper should not depart vertically with the cart and should instead leave horizontally into the wider corridor.",
    "abstraction": {
      "state_properties": {
        "shortVerticalShelfBay": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthV",
                2
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "shortVerticalShelfBay",
          {
            "or": [
              "N",
              "S"
            ]
          }
        ]
      }
    }
  }
]
